<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { Layers, PanelLeftClose, PanelLeftOpen, Search, Bell, ChevronRight, LogOut, UserRound, Settings, X, LayoutDashboard } from '@lucide/vue'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuLabel } from '@/components/ui/dropdown-menu'
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from '@/components/ui/sheet'
import DisplaySettings from '@/components/DisplaySettings.vue'
import NavigationTree from '@/components/NavigationTree.vue'
import SecurityControls from '@/components/SecurityControls.vue'
import AvatarImage from '@/components/AvatarImage.vue'
import BrandingFooter from '@/components/BrandingFooter.vue'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { useAuth } from '@/stores/auth'
import { usePreferences } from '@/stores/preferences'
import { useBranding } from '@/stores/branding'
import { useMessages } from '@/stores/messages'
import { filterMenus, findMenu } from '@/lib/menus'
import { trackPageTab, type WorkspaceTab } from '@/lib/tabs'
const route = useRoute(), router = useRouter(), { t } = useI18n(), auth = useAuth(), preferences = usePreferences(), branding = useBranding(), messages = useMessages()
const security = ref<InstanceType<typeof SecurityControls>>()
const collapsed = ref(false), mobileOpen = ref(false), query = ref(''), activeNav = ref('')
const menus = computed(() => { const current = auth.user?.navigation.find(n => n.id === activeNav.value); return filterMenus((auth.user?.menus || []).filter(m => !current || current.menuIds.includes(m.id)), query.value) })
const currentMenu = computed(() => findMenu(auth.user?.menus || [], menu => menu.path === route.path))
const title = computed(() => currentMenu.value?.name || (typeof route.meta.titleKey === 'string' ? t(route.meta.titleKey) : t('common.workspace')))
const count = computed(() => Number(messages.summary.unreadNotices) + Number(messages.summary.pendingTodos) + Number(messages.summary.unreadMessages))
const countLabel = computed(() => count.value > 99 ? '99+' : String(count.value))
const tabs = ref<WorkspaceTab[]>([]), tabKey = computed(() => 'sma.next.tabs.' + auth.user?.id)
watch(() => auth.user?.id, () => { tabs.value = []; if (!preferences.keepTabsAfterReload) return; try { const stored = JSON.parse(localStorage.getItem(tabKey.value) || '[]'); if (Array.isArray(stored)) tabs.value = stored.filter(tab => typeof tab.path === 'string' && tab.path.startsWith('/') && !tab.path.startsWith('//')).slice(0, 30) } catch { /* Ignore invalid persisted UI preferences. */ } }, { immediate: true })
watch(() => route.fullPath, () => { tabs.value = trackPageTab(tabs.value, { path: route.fullPath, titleKey: typeof route.meta.titleKey === 'string' ? route.meta.titleKey : undefined, fallback: title.value }, path => path.split('?')[0] || '/'); mobileOpen.value = false }, { immediate: true })
watch([tabs, () => preferences.keepTabsAfterReload], () => { if (preferences.keepTabsAfterReload) localStorage.setItem(tabKey.value, JSON.stringify(tabs.value)); else localStorage.removeItem(tabKey.value) }, { deep: true })
watch(() => auth.user?.locked, locked => { if (locked) messages.pause(); else void messages.connect() })
function label(tab: WorkspaceTab) { return tab.titleKey ? t(tab.titleKey) : findMenu(auth.user?.menus || [], menu => menu.path === tab.path.split('?')[0])?.name || tab.fallback }
function close(tab: WorkspaceTab) { const index = tabs.value.indexOf(tab); tabs.value = tabs.value.filter(item => item !== tab); if (route.fullPath === tab.path) void router.push(tabs.value[Math.max(0, index - 1)]?.path || '/') }
async function logout() { messages.stop(); await auth.logout(); await router.replace('/login') }
onMounted(() => { void branding.load(); messages.start() })
onUnmounted(() => messages.stop())
</script>
<template>
  <div class="min-h-dvh lg:grid" :class="collapsed ? 'lg:grid-cols-[76px_minmax(0,1fr)]' : 'lg:grid-cols-[248px_minmax(0,1fr)]'">
    <aside class="sticky top-0 hidden h-dvh flex-col border-r bg-card lg:flex"><RouterLink to="/" class="flex h-[72px] shrink-0 items-center gap-3 px-5"><div class="flex size-9 shrink-0 items-center justify-center rounded-xl bg-primary text-primary-foreground"><Layers class="size-5" /></div><div v-if="!collapsed" class="min-w-0"><p class="truncate text-sm font-semibold">{{ t('common.shortBrand') }}</p><p class="truncate text-xs text-muted-foreground">{{ t('common.workspace') }}</p></div></RouterLink><div v-if="!collapsed" class="relative mx-4 mb-4"><Search class="absolute top-2.5 left-3 size-4 text-muted-foreground" /><Input v-model="query" class="bg-background pl-9" :placeholder="t('common.search')" :aria-label="t('common.search')" /></div><nav class="min-h-0 flex-1 overflow-y-auto px-3" :aria-label="t('common.navigation')"><RouterLink to="/" class="mb-1 flex min-h-10 items-center gap-2.5 rounded-lg px-3 text-sm" :class="route.path === '/' ? 'bg-accent font-medium text-accent-foreground' : 'text-muted-foreground hover:bg-muted'" :title="collapsed ? t('common.home') : undefined"><LayoutDashboard class="size-[18px] shrink-0" /><span v-if="!collapsed">{{ t('common.home') }}</span></RouterLink><NavigationTree :items="menus" :collapsed="collapsed" /></nav><div class="m-3 border-t pt-3"><Button variant="ghost" class="w-full justify-start text-muted-foreground" :aria-label="t(collapsed ? 'common.expand' : 'common.collapse')" @click="collapsed = !collapsed"><PanelLeftOpen v-if="collapsed" class="size-4" /><PanelLeftClose v-else class="size-4" /><span v-if="!collapsed">{{ t('common.collapse') }}</span></Button></div></aside>
    <div class="min-w-0"><header class="sticky top-0 z-30 flex min-h-16 items-center justify-between gap-3 border-b bg-card/95 px-4 backdrop-blur md:px-7"><div class="flex min-w-0 items-center gap-3"><Button class="lg:hidden" variant="ghost" size="icon" :aria-label="t('common.expand')" @click="mobileOpen = true"><PanelLeftOpen class="size-5" /></Button><RouterLink to="/" class="hidden shrink-0 text-sm text-muted-foreground sm:block">{{ t('common.workspace') }}</RouterLink><ChevronRight class="hidden size-3.5 shrink-0 text-muted-foreground sm:block" /><span class="truncate text-sm font-medium">{{ title }}</span></div><div class="flex shrink-0 items-center gap-1"><Button variant="ghost" size="icon" class="relative" :aria-label="t('message.center')" @click="router.push('/message/inbox')"><Bell class="size-4" /><span v-if="count" class="absolute top-0 right-0 min-w-4 rounded-full bg-destructive px-1 text-[10px] leading-4 text-destructive-foreground">{{ countLabel }}</span></Button><DisplaySettings /><DropdownMenu><DropdownMenuTrigger as-child><Button variant="ghost" class="gap-2 px-1.5" :aria-label="t('common.account')"><AvatarImage :file-id="auth.user?.avatarFileId" :alt="auth.user?.name" :size="32" /><span class="hidden max-w-28 truncate text-sm md:inline">{{ auth.user?.name }}</span></Button></DropdownMenuTrigger><DropdownMenuContent align="end" class="w-52"><DropdownMenuLabel>{{ auth.user?.username }}</DropdownMenuLabel><DropdownMenuSeparator /><DropdownMenuItem @select="router.push('/profile')"><UserRound class="size-4" />{{ t('common.profile') }}</DropdownMenuItem><DropdownMenuItem @select="router.push('/preferences')"><Settings class="size-4" />{{ t('common.preferences') }}</DropdownMenuItem><DropdownMenuSeparator /><DropdownMenuItem @select="security?.lock()">{{ t('auth.lock') }}</DropdownMenuItem><DropdownMenuItem @select="security?.openPassword()">{{ t('auth.changePassword') }}</DropdownMenuItem><DropdownMenuSeparator /><DropdownMenuItem @select="logout"><LogOut class="size-4" />{{ t('common.signOut') }}</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div></header>
      <div v-if="auth.user?.navigation.length" class="flex gap-1 overflow-x-auto border-b bg-card px-4 py-2 md:px-7"><Button variant="ghost" size="sm" :class="{ 'bg-accent text-accent-foreground': !activeNav }" @click="activeNav = ''">{{ t('common.all') }}</Button><Button v-for="nav in auth.user.navigation" :key="nav.id" variant="ghost" size="sm" :class="{ 'bg-accent text-accent-foreground': activeNav === nav.id }" @click="activeNav = nav.id">{{ nav.name }}</Button></div>
      <div v-if="preferences.tabsEnabled" class="flex gap-1 overflow-x-auto border-b px-4 pt-2 md:px-7"><div v-for="tab in tabs" :key="tab.path.split('?')[0]" class="flex max-w-64 shrink-0 items-center rounded-t-md border border-b-0" :class="route.fullPath === tab.path ? 'border-border bg-card text-primary' : 'border-transparent text-muted-foreground'"><button class="truncate px-3 py-2 text-xs" @click="router.push(tab.path)">{{ label(tab) }}</button><button v-if="tab.path !== '/'" class="mr-1 rounded p-1 hover:bg-muted" :aria-label="t('common.closeTab', { name: label(tab) })" @click="close(tab)"><X class="size-3" /></button></div></div>
      <main class="mx-auto max-w-[1680px] p-4 md:p-7"><Alert v-if="auth.user?.passwordChangeSuggested" class="mb-5 border-[var(--warning)]/30 bg-[var(--warning)]/5"><AlertDescription class="flex flex-wrap items-center justify-between gap-2"><span>{{ t('auth.changeSuggested') }}</span><Button variant="outline" size="sm" @click="security?.openPassword()">{{ t('auth.changePassword') }}</Button></AlertDescription></Alert><RouterView /></main><footer class="px-7 py-5"><BrandingFooter /></footer>
    </div>
    <SecurityControls ref="security" /><Sheet v-model:open="mobileOpen"><SheetContent side="left" class="flex w-72 flex-col p-0"><SheetHeader class="border-b p-5"><SheetTitle>{{ branding.name }}</SheetTitle><SheetDescription>{{ t('common.navigation') }}</SheetDescription></SheetHeader><div class="px-4"><Input v-model="query" :placeholder="t('common.search')" :aria-label="t('common.search')" /></div><nav class="min-h-0 flex-1 overflow-y-auto px-3 pb-6" :aria-label="t('common.navigation')"><Button variant="ghost" class="mb-1 w-full justify-start" @click="router.push('/'); mobileOpen = false"><LayoutDashboard class="size-4" />{{ t('common.home') }}</Button><NavigationTree :items="menus" @navigate="mobileOpen = false" /></nav></SheetContent></Sheet>
  </div>
</template>
